18 |     .card h2 { font-size: 15px; font-weight: 600; margin-bottom: 16px; color: #1f2328; }
19 | 
20 |     label { display: block; font-size: 13px; font-weight: 500; margin-bottom: 4px; color: #57606a; }
21 |     input, select { width: 100%; padding: 8px 12px; border: 1px solid #e5e7eb; border-radius: 6px; font-size: 14px; background: #fff; margin-bottom: 16px; }
22 |     input:focus, select:focus { outline: none; border-color: #3b82d4; }
23 | 
24 |     .row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
25 | 
26 |     button#generate-btn {
27 |       background: #1f2328; color: #fff; border: none; border-radius: 6px;
28 |       padding: 10px 24px; font-size: 14px; font-weight: 600; cursor: pointer;
29 |     }
30 |     button#generate-btn:hover { background: #3b82d4; }
31 |     button#generate-btn:disabled { background: #8b949e; cursor: not-allowed; }
32 | 
33 |     .hidden { display: none; }
34 | 
35 |     .tabs { display: flex; gap: 0; border-bottom: 2px solid #e5e7eb; margin-bottom: 20px; }
36 |     .tab-btn {
37 |       padding: 8px 20px; font-size: 13px; font-weight: 500; color: #57606a;
38 |       background: none; border: none; border-bottom: 2px solid transparent;
39 |       cursor: pointer; margin-bottom: -2px;
40 |     }
41 |     .tab-btn.active { color: #3b82d4; border-bottom-color: #3b82d4; }
42 | 
43 |     .tab-panel { display: none; }
44 |     .tab-panel.active { display: block; }
45 | 
46 |     .before-after { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
47 |     .panel-box { background: #f7f8fa; border: 1px solid #e5e7eb; border-radius: 6px; padding: 16px; }
48 |     .panel-box h3 { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #57606a; margin-bottom: 12px; }
49 |     .panel-box pre { white-space: pre-wrap; font-size: 13px; font-family: "SF Mono", "Fira Code", monospace; color: #1f2328; }
50 | 
51 |     .blockers { background: #fff8ed; border: 1px solid #f3c26a; border-radius: 6px; padding: 14px 16px; margin-top: 16px; }
52 |     .blockers h3 { font-size: 13px; font-weight: 600; color: #9a5d00; margin-bottom: 8px; }
53 |     .blockers ul { padding-left: 18px; }
54 |     .blockers li { font-size: 13px; color: #7d4e00; margin-bottom: 4px; }
55 | 
56 |     #status { font-size: 13px; color: #57606a; margin-top: 12px; min-height: 20px; display: flex; align-items: center; gap: 8px; }
57 |     #status.error { color: #cf222e; }
58 | 
59 |     .spinner {
60 |       width: 14px; height: 14px; flex-shrink: 0;
61 |       border: 2px solid #e5e7eb; border-top-color: #3b82d4;
62 |       border-radius: 50%;
63 |       animation: spin 0.7s linear infinite;
64 |     }
65 |     @keyframes spin { to { transform: rotate(360deg); } }
66 | 
67 |     .progress-steps { font-size: 12px; color: #57606a; margin-top: 6px; }
68 |     .progress-steps span { display: inline-block; margin-right: 12px; opacity: 0.4; }
69 |     .progress-steps span.done { opacity: 1; color: #1a7f37; }
70 |     .progress-steps span.active { opacity: 1; color: #3b82d4; font-weight: 600; }
71 | 
72 |     .copy-btn {
73 |       float: right; font-size: 12px; padding: 4px 10px;
74 |       background: #fff; border: 1px solid #e5e7eb; border-radius: 4px; cursor: pointer;
75 |     }
76 |     .copy-btn:hover { background: #f7f8fa; }
77 |   </style>
78 | </head>
79 | <body>
80 | 
81 | <header>
82 |   <h1>⚡ Standup Sync</h1>
83 |   <span>Turn your git history into standup notes, Slack updates, and email digests</span>
84 | </header>
85 | 
86 | <main>
87 |   <!-- Input form -->
88 |   <div class="card">
89 |     <h2>Generate Summary</h2>
90 |     <label for="repo">Repository path or URL</label>
91 |     <input id="repo" type="text" placeholder="https://github.com/your-org/your-repo  or  /local/path/to/repo" />
92 | 
93 |     <div class="row">
94 |       <div>
95 |         <label for="since">Since</label>
96 |         <select id="since">
97 |           <option value="24 hours ago">Last 24 hours</option>
98 |           <option value="48 hours ago">Last 48 hours</option>
99 |           <option value="7 days ago">Last 7 days</option>
100 |           <option value="30 days ago">Last 30 days</option>
101 |         </select>
102 |       </div>
103 |       <div>
104 |         <label for="until">Until (optional)</label>
105 |         <input id="until" type="date" />
106 |       </div>
107 |     </div>
108 | 
109 |     <button id="generate-btn">Generate</button>
110 |     <div id="status"></div>
111 |     <div id="progress-steps" class="progress-steps hidden">
112 |       <span id="step-clone">① Clone repo</span>
113 |       <span id="step-extract">② Extract commits</span>
114 |       <span id="step-filter">③ Filter noise</span>
115 |       <span id="step-llm">④ Analyse diffs (LLM)</span>
116 |       <span id="step-render">⑤ Render output</span>
117 |     </div>
118 |   </div>
119 | 
120 |   <!-- Results -->
121 |   <div id="results" class="hidden">
122 | 
123 |     <!-- Before / After -->
124 |     <div class="card">
125 |       <h2>Before vs. After</h2>
126 |       <div class="before-after">
127 |         <div class="panel-box">
128 |           <h3>Raw git log</h3>
129 |           <pre id="raw-log"></pre>
130 |         </div>
131 |         <div class="panel-box">
132 |           <h3>Generated summary</h3>
133 |           <pre id="summary-preview"></pre>
134 |         </div>
135 |       </div>
136 |     </div>
137 | 
138 |     <!-- Blockers -->
139 |     <div id="blockers-section" class="hidden card">
140 |       <h2>⚠️ Possible Blockers</h2>
141 |       <ul id="blockers-list"></ul>
142 |     </div>
143 | 
144 |     <!-- Format outputs -->
145 |     <div class="card">
146 |       <h2>Output Formats</h2>
147 |       <div class="tabs">
148 |         <button class="tab-btn active" data-tab="slack">Slack</button>
149 |         <button class="tab-btn" data-tab="email">Email</button>
150 |         <button class="tab-btn" data-tab="standup">Standup</button>
151 |       </div>
152 | 
153 |       <div id="tab-slack" class="tab-panel active">
154 |         <button class="copy-btn" onclick="copyTab('slack')">Copy</button>
155 |         <pre id="output-slack"></pre>
156 |       </div>
157 |       <div id="tab-email" class="tab-panel">
158 |         <button class="copy-btn" onclick="copyTab('email')">Copy</button>
159 |         <pre id="output-email"></pre>
160 |       </div>
161 |       <div id="tab-standup" class="tab-panel">
162 |         <button class="copy-btn" onclick="copyTab('standup')">Copy</button>
163 |         <pre id="output-standup"></pre>
164 |       </div>
165 |     </div>
166 | 
167 |   </div>
168 | </main>
169 | 
170 | <script>
171 |   let currentFormats = {};
172 | 
173 |   // Map backend step names to UI step element IDs
174 |   const STEP_MAP = { clone: 'step-clone', filter: 'step-filter', llm: 'step-llm', group: 'step-llm', render: 'step-render' };
175 |   const ALL_STEPS = ['step-clone', 'step-extract', 'step-filter', 'step-llm', 'step-render'];
176 | 
177 |   document.getElementById('generate-btn').addEventListener('click', async () => {
178 |     const repo = document.getElementById('repo').value.trim();
179 |     const since = document.getElementById('since').value;
180 |     const until = document.getElementById('until').value || null;
181 |     const btn = document.getElementById('generate-btn');
182 |     const status = document.getElementById('status');
183 |     const stepsEl = document.getElementById('progress-steps');
184 | 
185 |     if (!repo) { status.innerHTML = 'Please enter a repository path or URL.'; status.className = 'error'; return; }
186 | 
187 |     // Reset UI
188 |     btn.disabled = true;
189 |     btn.textContent = 'Generating…';
190 |     status.className = '';
191 |     status.innerHTML = '<div class="spinner"></div><span>Starting…</span>';
192 |     document.getElementById('results').classList.add('hidden');
193 |     stepsEl.classList.remove('hidden');
194 |     ALL_STEPS.forEach(s => { document.getElementById(s).className = ''; });
195 | 
196 |     let activeStep = null;
197 | 
198 |     function setStep(stepId) {
199 |       if (activeStep && activeStep !== stepId) {
200 |         document.getElementById(activeStep).className = 'done';
201 |       }
202 |       document.getElementById(stepId).className = 'active';
203 |       activeStep = stepId;
204 |     }
205 | 
206 |     function finishSteps() {
207 |       ALL_STEPS.forEach(s => { document.getElementById(s).className = 'done'; });
208 |       stepsEl.classList.add('hidden');
209 |     }
210 | 
211 |     function showResult(data) {
212 |       currentFormats = data.formats;
213 |       document.getElementById('raw-log').textContent = data.summary.raw_log.join('\n');
214 |       document.getElementById('summary-preview').textContent = data.formats.slack;
215 | 
216 |       const blockersSection = document.getElementById('blockers-section');
217 |       const blockersList = document.getElementById('blockers-list');
218 |       blockersList.innerHTML = '';
219 |       if (data.summary.blockers.length > 0) {
220 |         blockersSection.classList.remove('hidden');
221 |         data.summary.blockers.forEach(b => {
222 |           const li = document.createElement('li');
223 |           if (b.reason === 'repeated_changes') {
224 |             li.textContent = `${b.target} was modified in 3+ commits — possible rework or ongoing issue.`;
225 |           } else {
226 |             li.textContent = `Commit ${b.target.slice(0,7)} flagged: "${b.message}" — possible struggle.`;
227 |           }
228 |           blockersList.appendChild(li);
229 |         });
230 |       } else {
231 |         blockersSection.classList.add('hidden');
232 |       }
233 | 
234 |       document.getElementById('output-slack').textContent = data.formats.slack;
235 |       document.getElementById('output-email').textContent = data.formats.email;
236 |       document.getElementById('output-standup').textContent = data.formats.standup;
237 |       document.getElementById('results').classList.remove('hidden');
238 |       status.innerHTML = `Done — ${data.summary.raw_log.length} commit(s) analysed.`;
239 |     }
240 | 
241 |     try {
242 |       const res = await fetch('/api/generate', {
243 |         method: 'POST',
244 |         headers: { 'Content-Type': 'application/json' },
245 |         body: JSON.stringify({ repo, since, until }),
246 |       });
247 | 
248 |       // Read the SSE stream manually
249 |       const reader = res.body.getReader();
250 |       const decoder = new TextDecoder();
251 |       let buffer = '';
252 | 
253 |       while (true) {
254 |         const { done, value } = await reader.read();
255 |         if (done) break;
256 |         buffer += decoder.decode(value, { stream: true });
257 | 
258 |         // SSE frames are separated by double newlines
259 |         const frames = buffer.split('\n\n');
260 |         buffer = frames.pop(); // keep incomplete frame in buffer
261 | 
262 |         for (const frame of frames) {
263 |           if (!frame.trim()) continue;
264 |           const eventMatch = frame.match(/^event: (\w+)/m);
265 |           const dataMatch = frame.match(/^data: (.+)/m);
266 |           if (!eventMatch || !dataMatch) continue;
267 | 
268 |           const eventType = eventMatch[1];
269 |           const payload = JSON.parse(dataMatch[1]);
270 | 
271 |           if (eventType === 'progress') {
272 |             const stepId = STEP_MAP[payload.step] || null;
273 |             if (stepId) setStep(stepId);
274 |             status.innerHTML = `<div class="spinner"></div><span>${payload.message}</span>`;
275 | 
276 |           } else if (eventType === 'raw_log') {
277 |             // Show raw log immediately — before LLM finishes
278 |             document.getElementById('raw-log').textContent = payload.lines.join('\n');
279 |             document.getElementById('results').classList.remove('hidden');
280 |             setStep('step-extract');
281 | 
282 |           } else if (eventType === 'result') {
283 |             finishSteps();
284 |             showResult(payload);
285 | 
286 |           } else if (eventType === 'error') {
287 |             finishSteps();
288 |             status.innerHTML = `Error: ${payload.detail}`;
289 |             status.className = 'error';
290 |           }
291 |         }
292 |       }
293 | 
294 |     } catch (err) {
295 |       finishSteps();
296 |       status.innerHTML = `Error: ${err.message}`;
297 |       status.className = 'error';
298 |     } finally {
299 |       btn.disabled = false;
300 |       btn.textContent = 'Generate';
301 |     }
302 |   });
303 | 
304 |   // Tab switching
305 |   document.querySelectorAll('.tab-btn').forEach(btn => {
306 |     btn.addEventListener('click', () => {
307 |       document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
308 |       document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));
309 |       btn.classList.add('active');
310 |       document.getElementById('tab-' + btn.dataset.tab).classList.add('active');
311 |     });
312 |   });
313 | 
314 |   function copyTab(format) {
315 |     navigator.clipboard.writeText(currentFormats[format] || '').then(() => {
316 |       const btn = event.target;
317 |       btn.textContent = 'Copied!';
318 |       setTimeout(() => btn.textContent = 'Copy', 1500);
319 |     });
320 |   }
321 | </script>
322 | </body>
323 | </html>
324 |

