/* ── Reset & Base ─────────────────────────────────────────────────────────── */
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: -apple-system, "Segoe UI", sans-serif; background: #f7f8fa; color: #1f2328; font-size: 14px; line-height: 1.6; }

/* ── Layout ───────────────────────────────────────────────────────────────── */
header { background: #1f2328; color: #fff; padding: 16px 32px; display: flex; align-items: center; gap: 12px; }
header h1 { font-size: 18px; font-weight: 600; }
header span { font-size: 13px; color: #8b949e; }

main { max-width: 1100px; margin: 32px auto; padding: 0 24px; }

/* ── Card ─────────────────────────────────────────────────────────────────── */
.card { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 24px; margin-bottom: 24px; }
.card h2 { font-size: 15px; font-weight: 600; margin-bottom: 16px; color: #1f2328; }

/* ── Form elements ────────────────────────────────────────────────────────── */
label { display: block; font-size: 13px; font-weight: 500; margin-bottom: 4px; color: #57606a; }
input, select { width: 100%; padding: 8px 12px; border: 1px solid #e5e7eb; border-radius: 6px; font-size: 14px; background: #fff; margin-bottom: 16px; }
input:focus, select:focus { outline: none; border-color: #3b82d4; }

.row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

button#generate-btn {
  background: #1f2328; color: #fff; border: none; border-radius: 6px;
  padding: 10px 24px; font-size: 14px; font-weight: 600; cursor: pointer;
}
button#generate-btn:hover { background: #3b82d4; }
button#generate-btn:disabled { background: #8b949e; cursor: not-allowed; }

/* ── Utility ──────────────────────────────────────────────────────────────── */
.hidden { display: none; }

/* ── Tabs ─────────────────────────────────────────────────────────────────── */
.tabs { display: flex; gap: 0; border-bottom: 2px solid #e5e7eb; margin-bottom: 20px; }
.tab-btn {
  padding: 8px 20px; font-size: 13px; font-weight: 500; color: #57606a;
  background: none; border: none; border-bottom: 2px solid transparent;
  cursor: pointer; margin-bottom: -2px;
}
.tab-btn.active { color: #3b82d4; border-bottom-color: #3b82d4; }

.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* ── Before / After panels ────────────────────────────────────────────────── */
.before-after { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.panel-box { background: #f7f8fa; border: 1px solid #e5e7eb; border-radius: 6px; padding: 16px; }
.panel-box h3 { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.05em; color: #57606a; margin-bottom: 12px; }
.panel-box pre { white-space: pre-wrap; font-size: 13px; font-family: "SF Mono", "Fira Code", monospace; color: #1f2328; }

/* ── Blockers ─────────────────────────────────────────────────────────────── */
.blockers { background: #fff8ed; border: 1px solid #f3c26a; border-radius: 6px; padding: 14px 16px; margin-top: 16px; }
.blockers h3 { font-size: 13px; font-weight: 600; color: #9a5d00; margin-bottom: 8px; }
.blockers ul { padding-left: 18px; }
.blockers li { font-size: 13px; color: #7d4e00; margin-bottom: 4px; }

/* ── Status & spinner ─────────────────────────────────────────────────────── */
#status { font-size: 13px; color: #57606a; margin-top: 12px; min-height: 20px; display: flex; align-items: center; gap: 8px; }
#status.error { color: #cf222e; }

.spinner {
  width: 14px; height: 14px; flex-shrink: 0;
  border: 2px solid #e5e7eb; border-top-color: #3b82d4;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ── Progress steps ───────────────────────────────────────────────────────── */
.progress-steps { font-size: 12px; color: #57606a; margin-top: 6px; }
.progress-steps span { display: inline-block; margin-right: 12px; opacity: 0.4; }
.progress-steps span.done { opacity: 1; color: #1a7f37; }
.progress-steps span.active { opacity: 1; color: #3b82d4; font-weight: 600; }

/* ── Copy button ──────────────────────────────────────────────────────────── */
.copy-btn {
  float: right; font-size: 12px; padding: 4px 10px;
  background: #fff; border: 1px solid #e5e7eb; border-radius: 4px; cursor: pointer;
}
.copy-btn:hover { background: #f7f8fa; }

/* ── Tone toggle ──────────────────────────────────────────────────────────── */
.formats-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.formats-header h2 { margin-bottom: 0; }
.tone-toggle { display: flex; border: 1px solid #e5e7eb; border-radius: 6px; overflow: hidden; }
.tone-btn {
  padding: 6px 14px; font-size: 12px; font-weight: 500; background: #fff;
  border: none; cursor: pointer; color: #57606a; white-space: nowrap;
}
.tone-btn + .tone-btn { border-left: 1px solid #e5e7eb; }
.tone-btn.active { background: #1f2328; color: #fff; }
.tone-btn:not(.active):hover { background: #f7f8fa; }

/* ── Developer Stats table ────────────────────────────────────────────────── */
.stats-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.stats-table th {
  text-align: right; font-weight: 600; font-size: 12px; color: #57606a;
  padding: 6px 10px; border-bottom: 2px solid #e5e7eb; white-space: nowrap;
}
.stats-table th:first-child { text-align: left; }
.stats-table td { padding: 7px 10px; border-bottom: 1px solid #f0f2f4; text-align: right; }
.stats-table td:first-child { text-align: left; font-weight: 500; }
.stats-table tbody tr:last-child td { border-bottom: none; }
.stats-table tbody tr:hover { background: #f7f8fa; }
.cell-added   { color: #1a7f37; font-weight: 500; }
.cell-deleted { color: #cf222e; font-weight: 500; }
.cell-updated { color: #3b82d4; font-weight: 500; }
.sort-btn {
  float: right; font-size: 11px; padding: 3px 9px; font-weight: 500;
  background: #f7f8fa; border: 1px solid #e5e7eb; border-radius: 4px;
  cursor: pointer; color: #57606a; margin-top: 1px;
}
.sort-btn:hover { background: #e5e7eb; }

/* ── Date range filter ────────────────────────────────────────────────────── */
.date-section { margin-bottom: 16px; }
.date-section-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.date-section-header label { margin-bottom: 0; }
.reset-btn {
  font-size: 11px; padding: 2px 8px; font-weight: 500;
  background: #fff; border: 1px solid #e5e7eb; border-radius: 4px;
  cursor: pointer; color: #57606a;
}
.reset-btn:hover { background: #f7f8fa; color: #cf222e; border-color: #f0a0a0; }
.radio-group { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.radio-option { display: flex; align-items: center; gap: 5px; cursor: pointer; }
.radio-option input[type="radio"] {
  width: auto; margin: 0; padding: 0; cursor: pointer;
  accent-color: #3b82d4;
}
.radio-option span {
  font-size: 13px; font-weight: 500; color: #1f2328;
  padding: 5px 12px; border: 1px solid #e5e7eb; border-radius: 20px;
  background: #fff; cursor: pointer; user-select: none;
  transition: background 0.1s, border-color 0.1s;
}
.radio-option input[type="radio"] { display: none; }
.radio-option input[type="radio"]:checked + span { background: #1f2328; color: #fff; border-color: #1f2328; }
.radio-option span:hover { border-color: #3b82d4; color: #3b82d4; }
.radio-option input[type="radio"]:checked + span:hover { background: #1f2328; color: #fff; border-color: #1f2328; }
.date-range-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.date-range-row .field label { font-size: 12px; color: #57606a; font-weight: 500; margin-bottom: 4px; }
.date-range-row input[type="date"] { margin-bottom: 0; }
.date-range-row.disabled input[type="date"] { background: #f7f8fa; color: #adb5bd; cursor: not-allowed; }
.date-range-error { font-size: 12px; color: #cf222e; margin-top: 6px; }
input.input-error { border-color: #cf222e !important; }

/* ── Tooltip ──────────────────────────────────────────────────────────────── */
.label-row { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; }
.label-row label { margin-bottom: 0; }
.tooltip-anchor { position: relative; display: inline-flex; }
.tooltip-icon {
  width: 15px; height: 15px; border-radius: 50%;
  background: #e5e7eb; color: #57606a;
  font-size: 10px; font-weight: 700; line-height: 15px;
  text-align: center; cursor: default; user-select: none; flex-shrink: 0;
}
.tooltip-box {
  display: none; position: absolute; left: 50%; bottom: calc(100% + 8px);
  transform: translateX(-50%);
  background: #1f2328; color: #fff;
  font-size: 12px; line-height: 1.5; font-weight: 400;
  padding: 10px 13px; border-radius: 6px;
  width: 280px; white-space: normal; z-index: 100;
  pointer-events: none;
}
.tooltip-box::after {
  content: ''; position: absolute; top: 100%; left: 50%;
  transform: translateX(-50%);
  border: 5px solid transparent; border-top-color: #1f2328;
}
.tooltip-anchor:hover .tooltip-box,
.tooltip-anchor:focus-within .tooltip-box { display: block; }

